// ── 🏯 mundo-santuario-zen · Director de Escena & Atmósfera ─────────────────────────────
//
// Configura automáticamente la atmósfera visual, iluminación nocturna calibrada,
// reflejos en agua en tiempo real, pétalos de sakura y luciérnagas vivas a 60 FPS estables.
//

// 1. Cargar librerías del ecosistema
await game.snippet("ambientes");
const P = await game.snippet("particulas-voxel");

// 2. Estado de la escena
let estadoNoche = false;
let estadoNiebla = false;

// Configurar emisión luminosa de bloques estáticos y antorchas (sin coste en movimiento)
game.glowLevel = 15;
game.glowFocus = 0.2;

// Atmósferas personalizadas para el Santuario Zen
const ATMOSFERA = {
  ATARDECER: {
    cielo: {
      horizonte: [1.00, 0.65, 0.25],
      medio:     [0.92, 0.35, 0.45],
      cenit:     [0.28, 0.15, 0.45],
      suelo:     [0.35, 0.20, 0.15]
    },
    niebla: { near: 45, far: 340, tinte: 0.05 },
    luz: 0.85,
    sombra: 0.55
  },
  NOCHE_LUMINOSA: {
    cielo: {
      horizonte: [0.16, 0.20, 0.38], // Azul zafiro lunar
      medio:     [0.09, 0.12, 0.24],
      cenit:     [0.04, 0.06, 0.14],
      suelo:     [0.06, 0.08, 0.14]
    },
    niebla: { near: 35, far: 220, tinte: 0.08 },
    luz: 0.55, // Noche clara y luminosa
    sombra: 0.65
  }
};

function aplicarAtmosfera(cfg, seg = 1.5) {
  game.cielo(cfg.cielo);
  game.niebla(cfg.niebla);
  game.luz(cfg.luz);
  game.sunShade = cfg.sombra;
}

// Configuración inicial: Atardecer
aplicarAtmosfera(ATMOSFERA.ATARDECER, 0);
game.reflejoEntorno = true;
game.reflejoOndas = true;
game.reflejoPlanoY = 10.0;

// 3. Sistema de partículas continuo: Pétalos de flor de cerezo (Sakura)
const petalosSakura = P.crea({
  grupo: 'sakura',
  porSegundo: 45,
  radio: 26,
  alto: 14,
  fondo: 20,
  fuerza: 0.8,
  grav: 1.2,
  deriva: 1.4,
  derivaHz: 0.3,
  dura: 14,
  desvanece: 4,
  vuelo: 18,
  posarse: true,
  muereEnFluido: false,
  colores: [
    [1.0, 0.72, 0.85],
    [0.98, 0.58, 0.76],
    [0.92, 0.45, 0.65],
    [1.0, 0.88, 0.94],
    [0.85, 0.35, 0.55]
  ]
});
petalosSakura.enciende(45);

// 4. Sistema de partículas continuo: Luciérnagas vivas
// Autoiluminadas en el shader overlay (emite: false para evitar recalcular BFS 3D dinámico cada frame)
if (game.voxelesUI && game.voxelesUI.material) {
  game.voxelesUI.material('luciernagas', { emite: false });
}

const luciernagas = P.crea({
  grupo: 'luciernagas',
  porSegundo: 20,
  radio: 24,
  alto: 4,
  fondo: 15,
  fuerza: 0.45,
  grav: -0.5,
  deriva: 1.2,
  derivaHz: 0.4,
  dura: 10,
  desvanece: 3,
  vuelo: 14,
  posarse: false,
  colores: [
    [1.0, 0.95, 0.45],
    [0.92, 1.0, 0.55],
    [1.0, 0.85, 0.3],
    [1.0, 1.0, 0.8]
  ]
});
luciernagas.enciende(20);

// 5. Mandos del Director y Cámara Cinemática Orbital
let cineRAF = null;
let cineActivo = false;
let estadoVolarPrev = false;
let estadoFantasmaPrev = false;

function toggleCamaraOrbital() {
  cineActivo = !cineActivo;
  if (!cineActivo) {
    if (cineRAF) cancelAnimationFrame(cineRAF);
    game.fantasma(estadoFantasmaPrev);
    game.volar(estadoVolarPrev);
    toast("🎥 Cámara libre restaurada");
    return;
  }
  estadoVolarPrev = !!(mc.volar);
  estadoFantasmaPrev = !!(mc.fantasma);
  game.volar(true);
  game.fantasma(true);

  toast("🎥 Cámara cinemática orbital (WASD para cancelar)");
  const centro = [48, 16, 48];
  const radio = 36;
  const altura = 21;
  const t0 = performance.now();

  function paso() {
    if (!cineActivo) return;
    const t = (performance.now() - t0) * 0.00015;
    mc.pos[0] = centro[0] + Math.cos(t) * radio;
    mc.pos[1] = altura + Math.sin(t * 0.5) * 1.5;
    mc.pos[2] = centro[2] + Math.sin(t) * radio;
    mc.vel = [0, 0, 0];

    const dx = centro[0] - mc.pos[0];
    const dz = centro[2] - mc.pos[2];
    mc.yaw = Math.atan2(-dx, -dz);
    mc.pitch = -0.16;
    cineRAF = requestAnimationFrame(paso);
  }
  paso();
}

window.addEventListener('keydown', (e) => {
  if (['w', 'a', 's', 'd', ' '].includes(e.key.toLowerCase()) && cineActivo) {
    cineActivo = false;
    if (cineRAF) cancelAnimationFrame(cineRAF);
    game.fantasma(estadoFantasmaPrev);
    game.volar(estadoVolarPrev);
  }
}, { capture: true });

// 6. Menú OSD (Tecla O) con SWITCHES reales
const htmlOSD = () => '<div class="mc-osd-panel">'
  + '<div class="mc-osd-title">🏯 SANTUARIO ZEN</div>'
  + '<button class="mc-osd-btn" data-osd="TOGGLE_NOCHE">🌙 NOCHE: ' + (estadoNoche ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="TOGGLE_NIEBLA">🌫️ NIEBLA: ' + (estadoNiebla ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="REFLEJOS">✨ REFLEJOS: ' + (game.reflejoEntorno ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="PETALOS">🌸 PÉTALOS: ' + (petalosSakura.porSegundo ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="LUCIERNAGAS">🏮 LUCIÉRNAGAS: ' + (luciernagas.porSegundo ? 'ON' : 'OFF') + '</button>'
  + '<button class="mc-osd-btn" data-osd="ORBITA">🎥 CÁMARA ORBITAL</button>'
  + '<button class="mc-osd-btn" data-osd="REC">🔴 GRABAR VÍDEO (Alt+V)</button>'
  + '<button class="mc-osd-btn">CERRAR</button>'
  + '</div>';

function refrescarEntorno() {
  if (estadoNiebla) {
    game.entorno('NIEBLA', 1.5);
  } else if (estadoNoche) {
    aplicarAtmosfera(ATMOSFERA.NOCHE_LUMINOSA, 1.5);
  } else {
    aplicarAtmosfera(ATMOSFERA.ATARDECER, 1.5);
  }
}

game.osd.define('menu_santuario', { sitio: 'abajo-derecha', showTool: false, html: htmlOSD() });

game.osd.alPulsar('TOGGLE_NOCHE', () => {
  estadoNoche = !estadoNoche;
  refrescarEntorno();
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});

game.osd.alPulsar('TOGGLE_NIEBLA', () => {
  estadoNiebla = !estadoNiebla;
  refrescarEntorno();
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});

game.osd.alPulsar('REFLEJOS', () => {
  game.reflejoEntorno = !game.reflejoEntorno;
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});

game.osd.alPulsar('PETALOS', () => {
  if (petalosSakura.porSegundo) { petalosSakura.para(); petalosSakura.limpia(); }
  else { petalosSakura.enciende(45); }
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});

game.osd.alPulsar('LUCIERNAGAS', () => {
  if (luciernagas.porSegundo) { luciernagas.para(); luciernagas.limpia(); }
  else { luciernagas.enciende(20); }
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});

game.osd.alPulsar('ORBITA', () => {
  game.osd.cerrar();
  toggleCamaraOrbital();
});

game.osd.alPulsar('REC', () => {
  game.osd.cerrar();
  if (typeof game.video !== 'undefined') game.video();
});

game.onKey('o', () => {
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', html: htmlOSD() });
  game.osd.abrir('menu_santuario');
});

toast('🏯 Santuario Zen listo · Tecla O menú de director · F foto · Alt+V vídeo', 6);
